import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiCalendar,
  FiMapPin,
  FiImage,
  FiUploadCloud,
  FiX,
} from 'react-icons/fi';

import api, { getApiErrorMessage } from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import { useLanguage } from '../../contexts/LanguageContext';


const AdminEvents = () => {

  const { t, language } = useLanguage();

  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingEvent, setEditingEvent] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    title_en: '',
    title_km: '',
    description_en: '',
    description_km: '',
    location_en: '',
    location_km: '',
    date: '',
    is_upcoming: true,
    is_past: false,
  });

  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState('');


  // ==========================================
  // CURRENT LANGUAGE FIELDS
  // ==========================================

  const titleField =
    language === 'km'
      ? 'title_km'
      : 'title_en';

  const descriptionField =
    language === 'km'
      ? 'description_km'
      : 'description_en';

  const locationField =
    language === 'km'
      ? 'location_km'
      : 'location_en';


  // ==========================================
  // FETCH EVENTS
  // ==========================================

  useEffect(() => {
    fetchEvents();
  }, []);


  const fetchEvents = async () => {

    try {

      setLoading(true);

      const response = await api.get(
        '/api/events/'
      );

      setEvents(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Error loading events:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          t('events.loadFailed')
        )
      );

    } finally {

      setLoading(false);

    }

  };


  // ==========================================
  // DATE
  // ==========================================

  const toDateInput = (value) => {

    if (!value) {
      return '';
    }

    return String(value).split('T')[0];

  };


  const formatDate = (value) => {

    if (!value) {
      return '-';
    }

    const dateOnly =
      String(value).split('T')[0];

    const parts =
      dateOnly.split('-');

    if (parts.length !== 3) {
      return '-';
    }

    const [
      year,
      month,
      day,
    ] = parts;

    if (!year || !month || !day) {
      return '-';
    }

    const date = new Date(
      Number(year),
      Number(month) - 1,
      Number(day)
    );

    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      return '-';
    }

    return date.toLocaleDateString(
      language === 'km'
        ? 'km-KH'
        : 'en-GB',
      {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
      }
    );

  };


  // ==========================================
  // DISPLAY EVENT TITLE
  // ==========================================

  const getEventTitle = (event) => {

    if (!event) {
      return '-';
    }

    if (language === 'km') {

      return (
        event.title_km ||
        event.title_en ||
        '-'
      );

    }

    return (
      event.title_en ||
      event.title_km ||
      '-'
    );

  };


  // ==========================================
  // DISPLAY LOCATION
  // ==========================================

  const getEventLocation = (event) => {

    if (!event) {
      return '';
    }

    if (language === 'km') {

      return (
        event.location_km ||
        event.location_en ||
        ''
      );

    }

    return (
      event.location_en ||
      event.location_km ||
      ''
    );

  };


  // ==========================================
  // RESET FORM
  // ==========================================

  const resetForm = () => {

    setEditingEvent(null);

    setFormData({
      title_en: '',
      title_km: '',
      description_en: '',
      description_km: '',
      location_en: '',
      location_km: '',
      date: '',
      is_upcoming: true,
      is_past: false,
    });

    if (
      imagePreview &&
      imagePreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(
        imagePreview
      );
    }

    setImageFile(null);
    setImagePreview('');

  };


  // ==========================================
  // ADD
  // ==========================================

  const handleAdd = () => {

    resetForm();

    setModalOpen(true);

  };


  // ==========================================
  // CLOSE
  // ==========================================

  const handleCloseModal = () => {

    setModalOpen(false);

    resetForm();

  };


  // ==========================================
  // INPUT CHANGE
  // ==========================================

  const handleChange = (e) => {

    const {
      name,
      value,
    } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

  };


  // ==========================================
  // IMAGE
  // ==========================================

  const handleImageChange = (e) => {

    const file =
      e.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];

    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        t('events.selectImage') ||
        'Please select JPG, JPEG, PNG or WEBP image.'
      );

      e.target.value = '';

      return;
    }

    const maxFileSize =
      5 * 1024 * 1024;

    if (
      file.size >
      maxFileSize
    ) {

      toast.error(
        t('events.imageTooLarge') ||
        'Image must be 5 MB or smaller.'
      );

      e.target.value = '';

      return;
    }

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }

    setImageFile(file);

    setImagePreview(
      URL.createObjectURL(file)
    );

  };


  const removeSelectedImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );

    }

    setImageFile(null);

    if (editingEvent?.image) {

      setImagePreview(
        editingEvent.image
      );

    } else {

      setImagePreview('');

    }

  };


  // ==========================================
  // SUBMIT
  // ==========================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    // ========================================
    // VALIDATE CURRENT LANGUAGE
    // ========================================

    if (
      !formData[
        titleField
      ].trim()
    ) {

      toast.error(
        t('events.titleRequired')
      );

      return;

    }


    if (!formData.date) {

      toast.error(
        t('events.dateRequired')
      );

      return;

    }


    if (
      !/^\d{4}-\d{2}-\d{2}$/.test(
        formData.date
      )
    ) {

      toast.error(
        t('events.invalidDate')
      );

      return;

    }


    try {

      setSubmitting(true);

      const payload =
        new FormData();


      // ======================================
      // BILINGUAL DATABASE FIELDS
      // ======================================

      payload.append(
        'title_en',
        formData.title_en.trim()
      );

      payload.append(
        'title_km',
        formData.title_km.trim()
      );

      payload.append(
        'description_en',
        formData.description_en.trim()
      );

      payload.append(
        'description_km',
        formData.description_km.trim()
      );

      payload.append(
        'location_en',
        formData.location_en.trim()
      );

      payload.append(
        'location_km',
        formData.location_km.trim()
      );


      // ======================================
      // COMMON FIELDS
      // ======================================

      payload.append(
        'date',
        formData.date
      );

      payload.append(
        'is_upcoming',
        String(
          formData.is_upcoming
        )
      );

      payload.append(
        'is_past',
        String(
          formData.is_past
        )
      );


      if (imageFile) {

        payload.append(
          'image_file',
          imageFile
        );

      }


      // ======================================
      // UPDATE
      // ======================================

      if (editingEvent) {

        await api.put(
          `/api/events/${editingEvent.id}`,
          payload
        );

        toast.success(
          t(
            'events.updatedSuccess'
          )
        );

      } else {

        // ====================================
        // CREATE
        // ====================================

        await api.post(
          '/api/events/',
          payload
        );

        toast.success(
          t(
            'events.createdSuccess'
          )
        );

      }


      handleCloseModal();

      await fetchEvents();

    } catch (error) {

      console.error(
        'Event operation error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          t(
            'common.operationFailed'
          )
        )
      );

    } finally {

      setSubmitting(false);

    }

  };


  // ==========================================
  // EDIT
  // ==========================================

  const handleEdit = (event) => {

    setEditingEvent(event);

    setFormData({
      title_en:
        event.title_en || '',

      title_km:
        event.title_km || '',

      description_en:
        event.description_en || '',

      description_km:
        event.description_km || '',

      location_en:
        event.location_en || '',

      location_km:
        event.location_km || '',

      date:
        toDateInput(
          event.date
        ),

      is_upcoming:
        Boolean(
          event.is_upcoming
        ),

      is_past:
        Boolean(
          event.is_past
        ),
    });

    setImageFile(null);

    setImagePreview(
      event.image || ''
    );

    setModalOpen(true);

  };


  // ==========================================
  // DELETE
  // ==========================================

  const handleDelete = async (id) => {

    const confirmed =
      window.confirm(
        t(
          'events.deleteConfirm'
        )
      );

    if (!confirmed) {
      return;
    }


    try {

      await api.delete(
        `/api/events/${id}`
      );

      toast.success(
        t(
          'events.deletedSuccess'
        )
      );

      await fetchEvents();

    } catch (error) {

      console.error(
        'Delete event error:',
        error
      );

      toast.error(
        getApiErrorMessage(
          error,
          t(
            'events.deleteFailed'
          )
        )
      );

    }

  };


  // ==========================================
  // TABLE COLUMNS
  // ==========================================

  const columns = [

    {
      key: 'title',

      label:
        t(
          'events.eventColumn'
        ),

      render: (_, row) => (

        <div className="min-w-[180px]">

          <p className="text-sm font-semibold text-blue-900">

            {getEventTitle(row)}

          </p>

        </div>

      ),
    },


    {
      key: 'date',

      label:
        t('common.date'),

      render: (value) => (

        <div className="flex items-center gap-2 text-sm text-blue-500 whitespace-nowrap">

          <FiCalendar
            className="text-red-600 flex-shrink-0"
            size={15}
          />

          <span>
            {formatDate(value)}
          </span>

        </div>

      ),
    },


    {
      key: 'location',

      label:
        t(
          'common.location'
        ),

      render: (_, row) => (

        <div className="flex items-center gap-2 text-sm text-blue-500 min-w-[150px]">

          <FiMapPin
            className="text-blue-900 flex-shrink-0"
            size={15}
          />

          <span className="truncate">

            {getEventLocation(
              row
            ) ||
              t(
                'common.notSpecified'
              )}

          </span>

        </div>

      ),
    },


    {
      key: 'is_upcoming',

      label:
        t('common.status'),

      render: (
        value,
        row
      ) => {

        const upcoming =
          Boolean(value) &&
          !row?.is_past;

        return (

          <span
            className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold ${
              upcoming
                ? 'bg-blue-50 text-blue-700 border border-blue-200'
                : 'bg-red-50 text-red-600 border border-red-100'
            }`}
          >

            <span
              className={`w-1.5 h-1.5 rounded-full ${
                upcoming
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }`}
            />

            {upcoming
              ? t(
                  'events.upcoming'
                )
              : t(
                  'events.past'
                )}

          </span>

        );

      },
    },


    {
      key: 'actions',

      label:
        t('common.actions'),

      render: (_, row) => (

        <div className="flex items-center gap-2">

          <button
            type="button"
            onClick={() =>
              handleEdit(row)
            }
            className="w-8 h-8 flex items-center justify-center bg-blue-50 text-blue-900 rounded-lg hover:bg-blue-900 hover:text-white transition-all duration-200"
            title={
              t('common.edit')
            }
          >

            <FiEdit2
              size={14}
            />

          </button>


          <button
            type="button"
            onClick={() =>
              handleDelete(
                row.id
              )
            }
            className="w-8 h-8 flex items-center justify-center bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all duration-200"
            title={
              t(
                'common.delete'
              )
            }
          >

            <FiTrash2
              size={14}
            />

          </button>

        </div>

      ),
    },

  ];


  // ==========================================
  // COUNTS
  // ==========================================

  const upcomingCount =
    events.filter(
      (event) =>
        event.is_upcoming &&
        !event.is_past
    ).length;


  const pastCount =
    events.filter(
      (event) =>
        event.is_past
    ).length;


  // ==========================================
  // RENDER
  // ==========================================

  return (

    <div
      className={`w-full ${
        language === 'km'
          ? 'font-khmer'
          : ''
      }`}
    >

      {/* ======================================
          HEADER
      ====================================== */}

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">

        <div className="flex items-center gap-3">

          <div className="w-10 h-10 bg-blue-900 text-white rounded-xl flex items-center justify-center shadow-sm">

            <FiCalendar
              size={18}
            />

          </div>


          <div>

            <h1 className="text-xl md:text-2xl font-bold text-blue-900">

              {t(
                'events.management'
              )}

            </h1>


            <p className="text-xs md:text-sm text-blue-400 mt-1">

              {t(
                'events.subtitle'
              )}

            </p>

          </div>

        </div>


        <button
          type="button"
          onClick={handleAdd}
          className="h-10 px-4 inline-flex items-center justify-center gap-2 bg-red-600 text-white rounded-lg text-sm font-semibold shadow-sm hover:bg-red-700 hover:shadow-md transition-all duration-200"
        >

          <FiPlus
            size={17}
          />

          {t(
            'events.addEvent'
          )}

        </button>

      </div>


      {/* ======================================
          STATS
      ====================================== */}

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-5">

        <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">

          <p className="text-xs text-blue-400">

            {t(
              'events.totalEvents'
            )}

          </p>

          <p className="text-2xl font-bold text-blue-900 mt-1">

            {events.length}

          </p>

        </div>


        <div className="bg-white border border-blue-200 rounded-xl p-4 shadow-sm">

          <p className="text-xs text-blue-400">

            {t(
              'events.upcoming'
            )}

          </p>

          <p className="text-2xl font-bold text-blue-600 mt-1">

            {upcomingCount}

          </p>

        </div>


        <div className="bg-white border border-red-100 rounded-xl p-4 shadow-sm">

          <p className="text-xs text-blue-400">

            {t(
              'events.pastEvents'
            )}

          </p>

          <p className="text-2xl font-bold text-red-600 mt-1">

            {pastCount}

          </p>

        </div>

      </div>


      {/* ======================================
          TABLE
      ====================================== */}

      <AdminCard className="overflow-hidden border border-blue-200 shadow-sm rounded-xl">

        <div className="px-5 py-4 border-b border-blue-200 flex items-center justify-between">

          <div>

            <h2 className="text-sm font-bold text-blue-900">

              {t(
                'events.allEvents'
              )}

            </h2>


            <p className="text-xs text-blue-300 mt-1">

              {events.length}{' '}

              {events.length === 1
                ? t(
                    'events.event'
                  )
                : t(
                    'events.events'
                  )}{' '}

              {t(
                'events.found'
              )}

            </p>

          </div>

        </div>


        <AdminTable
          columns={columns}
          data={events}
          loading={loading}
        />

      </AdminCard>


      {/* ======================================
          CREATE / EDIT MODAL
      ====================================== */}

      <AdminModal
        isOpen={modalOpen}
        onClose={
          handleCloseModal
        }
        title={
          editingEvent
            ? t(
                'events.editEvent'
              )
            : t(
                'events.createEvent'
              )
        }
      >

        <form
          onSubmit={
            handleSubmit
          }
        >

          <div className="space-y-5">


            {/* =================================
                EVENT TITLE
            ================================= */}

            <div>

              <label className="admin-label">

                {t(
                  'events.eventTitle'
                )}

                <span className="text-red-600">
                  {' '}*
                </span>

              </label>


              <input
                type="text"
                name={
                  titleField
                }
                value={
                  formData[
                    titleField
                  ]
                }
                onChange={
                  handleChange
                }
                placeholder={
                  t(
                    'events.eventTitlePlaceholder'
                  )
                }
                className={`admin-input ${
                  language === 'km'
                    ? 'font-khmer'
                    : ''
                }`}
                required
              />

            </div>


            {/* =================================
                DESCRIPTION
            ================================= */}

            <div>

              <label className="admin-label">

                {t(
                  'events.description'
                )}

              </label>


              <textarea
                name={
                  descriptionField
                }
                value={
                  formData[
                    descriptionField
                  ]
                }
                onChange={
                  handleChange
                }
                rows="4"
                placeholder={
                  t(
                    'events.descriptionPlaceholder'
                  )
                }
                className={`admin-input resize-none ${
                  language === 'km'
                    ? 'font-khmer'
                    : ''
                }`}
              />

            </div>


            {/* =================================
                LOCATION
            ================================= */}

            <div>

              <label className="admin-label">

                {t(
                  'events.location'
                )}

              </label>


              <div className="relative">

                <FiMapPin
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-blue-300"
                  size={15}
                />


                <input
                  type="text"
                  name={
                    locationField
                  }
                  value={
                    formData[
                      locationField
                    ]
                  }
                  onChange={
                    handleChange
                  }
                  placeholder={
                    t(
                      'events.locationPlaceholder'
                    )
                  }
                  className={`admin-input pl-9 ${
                    language === 'km'
                      ? 'font-khmer'
                      : ''
                  }`}
                />

              </div>

            </div>


            {/* =================================
                DATE
            ================================= */}

            <div>

              <label className="admin-label">

                {t(
                  'events.eventDate'
                )}

                <span className="text-red-600">
                  {' '}*
                </span>

              </label>


              <input
                type="date"
                name="date"
                value={
                  formData.date
                }
                onChange={
                  handleChange
                }
                className="admin-input"
                required
              />

            </div>


            {/* =================================
                IMAGE
            ================================= */}

            <div>

              <label className="admin-label">

                {editingEvent
                  ? t(
                      'events.changeEventImage'
                    )
                  : t(
                      'events.eventImage'
                    )}

              </label>


              {!imagePreview ? (

                <label className="min-h-[130px] border-2 border-dashed border-blue-200 rounded-xl flex flex-col items-center justify-center cursor-pointer bg-blue-50 hover:border-blue-400 transition-all">

                  <FiUploadCloud
                    size={27}
                    className="text-blue-900 mb-2"
                  />


                  <p className="text-sm font-semibold text-blue-900">

                    {t(
                      'events.clickUpload'
                    )}

                  </p>


                  <p className="text-[11px] text-blue-300 mt-1">

                    JPG, JPEG, PNG, WEBP — Max 5 MB

                  </p>


                  <input
                    type="file"
                    accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                    onChange={
                      handleImageChange
                    }
                    className="hidden"
                  />

                </label>

              ) : (

                <div className="relative w-full h-[180px] rounded-xl overflow-hidden bg-blue-50 border border-blue-200">

                  <img
                    src={
                      imagePreview
                    }
                    alt={
                      editingEvent
                        ? getEventTitle(
                            editingEvent
                          )
                        : t(
                            'events.eventImage'
                          )
                    }
                    className="w-full h-full object-cover"
                  />


                  <button
                    type="button"
                    onClick={
                      removeSelectedImage
                    }
                    className="absolute top-2 right-2 w-8 h-8 bg-black/60 text-white rounded-full flex items-center justify-center hover:bg-red-600 transition"
                    title={
                      t(
                        'common.remove'
                      )
                    }
                  >

                    <FiX
                      size={15}
                    />

                  </button>


                  <label className="absolute left-3 bottom-3 inline-flex items-center gap-2 px-3 py-2 bg-white text-blue-900 rounded-lg text-xs font-semibold shadow-md cursor-pointer hover:bg-blue-900 hover:text-white transition">

                    <FiImage />

                    {t(
                      'events.changeImage'
                    )}


                    <input
                      type="file"
                      accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                      onChange={
                        handleImageChange
                      }
                      className="hidden"
                    />

                  </label>

                </div>

              )}


              {editingEvent &&
                !imageFile &&
                imagePreview && (

                  <p className="text-[11px] text-blue-300 mt-1.5">

                    {t(
                      'events.keepCurrentImage'
                    )}

                  </p>

                )}

            </div>


            {/* =================================
                STATUS
            ================================= */}

            <div>

              <label className="admin-label">

                {t(
                  'events.eventStatus'
                )}

              </label>


              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">


                {/* UPCOMING */}

                <label
                  className={`cursor-pointer flex items-center gap-3 p-3 rounded-xl border transition-all ${
                    formData.is_upcoming
                      ? 'border-blue-300 bg-blue-50'
                      : 'border-blue-200 bg-white'
                  }`}
                >

                  <input
                    type="checkbox"
                    checked={
                      formData.is_upcoming
                    }
                    onChange={(e) =>
                      setFormData(
                        (prev) => ({
                          ...prev,

                          is_upcoming:
                            e.target
                              .checked,

                          is_past:
                            e.target
                              .checked
                              ? false
                              : prev.is_past,
                        })
                      )
                    }
                    className="w-4 h-4 accent-blue-600"
                  />


                  <div>

                    <p className="text-sm font-semibold text-blue-900">

                      {t(
                        'events.upcoming'
                      )}

                    </p>


                    <p className="text-[10px] text-blue-300">

                      {t(
                        'events.futureEvent'
                      )}

                    </p>

                  </div>

                </label>


                {/* PAST */}

                <label
                  className={`cursor-pointer flex items-center gap-3 p-3 rounded-xl border transition-all ${
                    formData.is_past
                      ? 'border-red-300 bg-red-50'
                      : 'border-blue-200 bg-white'
                  }`}
                >

                  <input
                    type="checkbox"
                    checked={
                      formData.is_past
                    }
                    onChange={(e) =>
                      setFormData(
                        (prev) => ({
                          ...prev,

                          is_past:
                            e.target
                              .checked,

                          is_upcoming:
                            e.target
                              .checked
                              ? false
                              : prev.is_upcoming,
                        })
                      )
                    }
                    className="w-4 h-4 accent-red-600"
                  />


                  <div>

                    <p className="text-sm font-semibold text-blue-900">

                      {t(
                        'events.past'
                      )}

                    </p>


                    <p className="text-[10px] text-blue-300">

                      {t(
                        'events.completedEvent'
                      )}

                    </p>

                  </div>

                </label>

              </div>

            </div>

          </div>


          {/* =================================
              BUTTONS
          ================================= */}

          <div className="mt-6 pt-4 border-t border-blue-200 flex items-center justify-end gap-3">

            <button
              type="button"
              onClick={
                handleCloseModal
              }
              disabled={
                submitting
              }
              className="h-10 px-4 border border-blue-200 bg-white text-blue-400 rounded-lg text-sm font-semibold hover:bg-blue-50 disabled:opacity-50 disabled:cursor-not-allowed transition"
            >

              {t(
                'common.cancel'
              )}

            </button>


            <button
              type="submit"
              disabled={
                submitting
              }
              className="min-w-[120px] h-10 px-5 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
            >

              {submitting
                ? editingEvent
                  ? t(
                      'events.updating'
                    )
                  : t(
                      'events.creating'
                    )
                : editingEvent
                ? t(
                    'events.updateEvent'
                  )
                : t(
                    'events.createEvent'
                  )}

            </button>

          </div>

        </form>

      </AdminModal>

    </div>

  );

};


export default AdminEvents;
